import{z as A,x as d,o as E,c as B,q as l,j as n,D as t,d as r,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Seq2Seq 编码解码","description":"","frontmatter":{"title":"Seq2Seq 编码解码","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/seq2seq-encode-decode.md","filePath":"llm/seq2seq-encode-decode.md","lastUpdated":1791063341000}'),m={name:"llm/seq2seq-encode-decode.md"};function h(p,e,c,_,q,u){const s=d("Mermaid");return E(),B("div",null,[e[2]||(e[2]=l('<h1 id="seq2seq-编码解码" tabindex="-1">Seq2Seq 编码解码 <a class="header-anchor" href="#seq2seq-编码解码" aria-label="Permalink to &quot;Seq2Seq 编码解码&quot;">​</a></h1><div class="epigraph"><p>一个循环网把源序列压成定长向量，另一个循环网把它展开成目标序列；两端长度可以不同，中间却只有那一个向量。</p><footer>—— 据 Sutskever, Vinyals &amp; Le, Sequence to Sequence Learning with Neural Networks, NeurIPS 2014；Cho et al., EMNLP 2014 整理</footer></div><p><a href="/llm/gru-vs-lstm">GRU 对照</a>给出可训的门控递推。本课不比较门的个数。缺口是：翻译、摘要要把一条序列映成<strong>另一条</strong>序列，长度不必相等，也不能逐步要求源与目标对齐在同一 \\(t\\)。方法是编码器—解码器：编码器读完源，交出最终状态（或若干层的最终状态）；解码器以之为初值，按下一词分类吐出目标。Teacher forcing 与注意力是后课；本课先把瓶颈暴露出来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言模型的条件是目标自己的前缀。跨语言时，条件应是另一条符号串。若强行把源与目标拼成一条再做语言模型，分界与长度会纠缠，且源侧没有「读完再写」的阶段。缺口是两个循环角色：编码器只读源，不预测目标词；解码器只写目标，每步的输入是已写出的目标符号（训练时可以是真值，下一课）。交接物是固定维向量 \\(s\\)，通常取编码器最后一步的 \\(h_n\\)。</p><p>\\(s\\) 必须承载整句信息。源一长，\\(n\\) 步压缩进固定 \\(d\\) 维，就是信息瓶颈。Sutskever 等人用大 LSTM 与倒序源缓解，但几何上瓶颈仍在。本课把这个「单一向量交接」写成定义，以便注意力课有明确要拆的对象。</p><p><span class="marginnote">直觉类比：定长向量 s 像一张便签——编码器读完整段话，只能写一张固定大小的便签递给解码器。五句话的事写一张便签还行；五十句话也要挤同一张便签，先说的内容必然被后说的挤掉。</span></p><h3 id="编码器不是自编码器里的重构" tabindex="-1">编码器不是自编码器里的重构 <a class="header-anchor" href="#编码器不是自编码器里的重构" aria-label="Permalink to &quot;编码器不是自编码器里的重构&quot;">​</a></h3><p>Seq2Seq 的损失只在目标符号的下一词交叉熵上，不要求把源重构回来。编码器可以丢掉对翻译无用的源细节。把架构理解成「压缩—解压同一句话」，会误用重构损失，也解释不了源语言与目标语言词表不同。两端可以是不同词表、不同嵌入表，只共享交接向量的维数。</p><p><span class="marginnote">实现：编码器双向时，正向与反向最终状态拼接成 \\(s\\)，解码器初始状态由线性层映回。双向增加的是源侧上下文，不是注意力；解码器仍只看见一个 \\(s\\)。</span></p><p><span class="marginnote">常见误区：把编码器—解码器当成自编码器，以为目标是把源句原样重构出来。实际损失只算目标语言下一词的交叉熵，编码器完全可以（也应该）丢掉对翻译没用的源侧细节，比如原文的拼写错误和啰嗦的插入语。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编码器：\\(h_t^{\\mathrm{enc}}=f_{\\mathrm{enc}}(h_{t-1}^{\\mathrm{enc}},x_t)\\)，\\(s=h_{n}^{\\mathrm{enc}}\\)。解码器：\\(h_t^{\\mathrm{dec}}=f_{\\mathrm{dec}}(h_{t-1}^{\\mathrm{dec}},y_{t-1})\\)，\\(h_0^{\\mathrm{dec}}=s\\)，每步 \\(z_t=\\mathrm{Linear}(h_t^{\\mathrm{dec}})\\) 对目标词表做交叉熵。推理时 \\(y_{t-1}\\) 来自上一步抽样或贪婪；训练时常用真值 \\(y_{t-1}\\)。长度不同完全合法：源 \\(n\\) 与目标 \\(m\\) 只在各自循环里出现。</p>',13)),(E(),n(i,null,{default:t(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20SRC%5B%22%E6%BA%90%E5%BA%8F%E5%88%97%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20RNN%22%5D%0A%20%20ENC%20--%3E%20S%5B%22%E5%AE%9A%E9%95%BF%E5%90%91%E9%87%8F%20s%22%5D%0A%20%20S%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%20RNN%22%5D%0A%20%20DEC%20--%3E%20TGT%5B%22%E7%9B%AE%E6%A0%87%E8%AF%8D%E5%BA%8F%E5%88%97%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=a("p",null,"变长到变长被拆成「变长到定长」加「定长到变长」。第一段的信息损失不可逆：解码器无法回头问编码器某一个词——它手里只有 \\(s\\)。短句上这够用；长句上 \\(s\\) 被后期源符号覆盖（RNN 的近因偏置），早期对齐线索消失。这不是实现没训好，是接口只允许一次交接。",-1)),e[5]||(e[5]=a("p",null,"倒序源（Sutskever 等人的技巧）让源的句首靠近交接时刻，缓解近因，但不增加 \\(s\\) 的维数，只是重新安排哪些源符号最后写入。多层编码器同样只改变 \\(s\\) 的质量，不改变「只有一个向量」这条。要按目标位置读取不同的源片段，必须留下全体 \\(h_j\\)，那是注意力课。",-1)),e[6]||(e[6]=a("p",null,"瓶颈随句长怎么失效：",-1)),(E(),n(i,null,{default:t(()=>[o(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHORT%5B%22%E7%9F%AD%E5%8F%A5%EF%BC%9A%E7%BA%A6%205%20%E8%AF%8D%22%5D%20--%3E%20P1%5B%225%20%E8%AF%8D%E4%BF%A1%E6%81%AF%E5%8E%8B%E8%BF%9B%20d%20%E7%BB%B4%E5%90%91%E9%87%8F%EF%BC%9A%E6%94%BE%E5%BE%97%E4%B8%8B%22%5D%0A%20%20SHORT%20--%3E%20OK%5B%22%E8%A7%A3%E7%A0%81%E5%AE%8C%E6%95%B4%22%5D%0A%20%20LONG%5B%22%E9%95%BF%E5%8F%A5%EF%BC%9A%E7%BA%A6%2060%20%E8%AF%8D%22%5D%20--%3E%20P2%5B%22%E5%90%8C%E6%A0%B7%E7%9A%84%20d%20%E7%BB%B4%EF%BC%9A%E6%97%A9%E6%9C%9F%E8%AF%8D%E8%A2%AB%E5%8F%A5%E5%B0%BE%E8%A6%86%E7%9B%96%22%5D%0A%20%20P2%20--%3E%20REC%5B%22RNN%20%E8%BF%91%E5%9B%A0%E5%81%8F%E7%BD%AE%EF%BC%9A%E5%8F%A5%E5%B0%BE%E6%9C%80%E6%B8%85%E6%99%B0%22%5D%0A%20%20REC%20--%3E%20FAIL%5B%22%E8%A7%A3%E7%A0%81%E5%BC%80%E5%A4%B4%E5%B0%B1%E4%B8%A2%E7%BA%BF%E7%B4%A2%EF%BC%9A%E6%BC%8F%E8%AF%91%E3%80%81%E9%94%99%E8%AF%91%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<p><span class="marginnote">数字实例：设 d=512 维、每个数 4 字节，交接向量总共约 2 KB。塞一句 60 词的长句，平均每个源词只摊到约 34 字节——这就是「几何上瓶颈仍在」的具体含义，也是后来注意力要留下全部隐状态的动机。</span></p><p>计算上仍两次串行循环。相对稍后的注意力，这里的优点是推理时编码器可以丢掉源端全体隐状态，只留 \\(s\\)；缺点正是丢掉了它们。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 teacher forcing 的训练—推理落差，不写对齐。下一课<a href="/llm/teacher-forcing">Teacher forcing</a>专门处理解码器输入用真值还是用自身预测。后课默认：序列到序列的基线是编码解码加定长瓶颈；注意力将针对「只有 \\(s\\)」这一缺口，而不是重写门控。多任务共用一个编码器仍只交出各自的 \\(s\\)，瓶颈形状不变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编码器把源压成定长 \\(s\\)，解码器从 \\(s\\) 展开目标，两端长度独立。</li><li>损失只在目标下一词，不是源的重构。</li><li>单一向量交接是长句对齐失败的结构原因。</li><li>双向编码仍只交出一个（拼接后的）\\(s\\)。</li><li>倒序源只改写入次序，不增加交接维数。</li><li>出处：Sutskever et al., NeurIPS 2014；Cho et al., EMNLP 2014。</li></ul>',6))])}const f=A(m,[["render",h]]);export{F as __pageData,f as default};
